package cn.iocoder.yudao.module.statistics.service.dashboard;
import cn.iocoder.yudao.framework.common.pojo.PageResult;import cn.iocoder.yudao.framework.tenant.core.context.TenantContextHolder;import cn.iocoder.yudao.module.product.api.spu.ProductSpuApi;import cn.iocoder.yudao.module.product.api.spu.dto.ProductSpuRespDTO;import cn.iocoder.yudao.module.statistics.controller.admin.dashboard.vo.*;import cn.iocoder.yudao.module.statistics.dal.dataobject.dashboard.TrafficDailyDO;import cn.iocoder.yudao.module.statistics.dal.dataobject.product.ProductStatisticsDO;import cn.iocoder.yudao.module.statistics.dal.mysql.dashboard.TrafficDailyMapper;import cn.iocoder.yudao.module.statistics.dal.mysql.product.ProductStatisticsMapper;import org.junit.jupiter.api.*;import org.springframework.test.util.ReflectionTestUtils;import java.time.*;import java.util.*;import static cn.iocoder.yudao.framework.common.pojo.CommonResult.success;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.ArgumentMatchers.*;import static org.mockito.Mockito.*;
class DashboardQueryServiceImplTest {
 @BeforeEach void setTenant(){TenantContextHolder.setTenantId(121L);}
 @AfterEach void clearTenant(){TenantContextHolder.clear();}
 @Test void ordinaryQuery_omitsProfitAndKeepsUnknownTraffic(){TrafficDailyMapper traffic=mock(TrafficDailyMapper.class);ProductStatisticsMapper products=mock(ProductStatisticsMapper.class);when(traffic.selectBetween(any(),any())).thenReturn(Collections.singletonList(new TrafficDailyDO().setDay(LocalDate.now().minusDays(1)).setProductDetailPv(null).setPaidOrderCount(3L).setPaidRevenue(1000L).setKnownCostAmount(500L).setCostAmount(500L).setGrossProfit(500L).setTrafficDataStatus(3)));DashboardQueryServiceImpl s=service(traffic,products);DashboardSummaryRespVO result=s.summary(new DashboardQueryReqVO(),false);assertFalse(result.getProfitVisible());assertNull(result.getKnownCostAmount());assertNull(result.getGrossProfit());assertNull(result.getBrowseOrderConversionPercent());assertEquals("UNAVAILABLE",result.getTrafficDataStatus());}
 @Test void partialSiteTrafficReturnsNullTrafficMetricsButPreservesTrade(){TrafficDailyMapper traffic=mock(TrafficDailyMapper.class);when(traffic.selectBetween(any(),any())).thenReturn(Arrays.asList(new TrafficDailyDO().setDay(LocalDate.now().minusDays(2)).setHomePv(20L).setHomeUv(10L).setProductDetailPv(30L).setProductDetailUv(15L).setAddCartCount(4L).setAddCartUserCount(3L).setCheckoutStartCount(2L).setPaidOrderCount(5L).setPaidRevenue(1000L).setRefundAmount(100L).setTrafficDataStatus(1),new TrafficDailyDO().setDay(LocalDate.now().minusDays(1)).setHomePv(8L).setProductDetailPv(9L).setPaidOrderCount(2L).setPaidRevenue(500L).setRefundAmount(0L).setTrafficDataStatus(2)));DashboardSummaryRespVO result=service(traffic,mock(ProductStatisticsMapper.class)).summary(new DashboardQueryReqVO().setScope("SITE"),false);assertEquals("PARTIAL",result.getTrafficDataStatus());assertNull(result.getHomePv());assertNull(result.getHomeUv());assertNull(result.getProductDetailPv());assertNull(result.getProductDetailUv());assertNull(result.getBrowseOrderConversionPercent());assertEquals(Long.valueOf(4L),result.getAddCartCount());assertEquals(Long.valueOf(7L),result.getPaidOrderCount());assertEquals(Long.valueOf(1400L),result.getNetRevenue());}
 @Test void unavailableProductTrafficReturnsNullTrafficMetricsButPreservesTrade(){ProductStatisticsMapper products=mock(ProductStatisticsMapper.class);when(products.selectDashboardSummary(eq(121L),any(),any(),isNull(),isNull())).thenReturn(new ProductStatisticsDO().setSpuId(1L).setBrowseCount(20L).setBrowseUserCount(10L).setCartCount(4L).setOrderCount(3L).setOrderPayCount(2L).setOrderPayPrice(1000L).setAfterSaleRefundPrice(100L).setTrafficDataStatus(3));DashboardSummaryRespVO result=service(mock(TrafficDailyMapper.class),products).summary(new DashboardQueryReqVO().setScope("PRODUCT"),false);assertEquals("UNAVAILABLE",result.getTrafficDataStatus());assertNull(result.getProductDetailPv());assertNull(result.getProductDetailUv());assertNull(result.getBrowseOrderConversionPercent());assertEquals(Long.valueOf(4L),result.getAddCartCount());assertEquals(Long.valueOf(3L),result.getPaidOrderCount());assertEquals(Long.valueOf(900L),result.getNetRevenue());verify(products,never()).selectBetween(any(),any());}
 @Test void summaryCompareUsesImmediatelyPrecedingEqualRangeAndDisclosesTrafficStart(){TrafficDailyMapper traffic=mock(TrafficDailyMapper.class);LocalDate start=LocalDate.of(2026,7,1),end=LocalDate.of(2026,7,3),referenceStart=LocalDate.of(2026,6,28),referenceEnd=LocalDate.of(2026,6,30);when(traffic.selectBetween(start,end)).thenReturn(Arrays.asList(new TrafficDailyDO().setDay(start).setHomePv(120L).setProductDetailPv(100L).setPaidOrderCount(20L).setPaidRevenue(2000L).setRefundAmount(100L).setTrafficDataStatus(1).setTrafficWatermark(LocalDateTime.now()),new TrafficDailyDO().setDay(end).setHomePv(80L).setProductDetailPv(100L).setPaidOrderCount(20L).setPaidRevenue(2000L).setRefundAmount(100L).setTrafficDataStatus(1).setTrafficWatermark(LocalDateTime.now())));when(traffic.selectBetween(referenceStart,referenceEnd)).thenReturn(Collections.singletonList(new TrafficDailyDO().setDay(referenceStart).setHomePv(100L).setProductDetailPv(100L).setPaidOrderCount(10L).setPaidRevenue(3000L).setRefundAmount(0L).setTrafficDataStatus(1).setTrafficWatermark(LocalDateTime.now())));DashboardSummaryRespVO result=service(traffic,mock(ProductStatisticsMapper.class)).summary(new DashboardQueryReqVO().setScope("SITE").setStartDate(start).setEndDate(end).setCompare(true),false);assertEquals(start,result.getTrafficDataAvailableFrom());assertEquals(referenceStart,result.getComparisonStartDate());assertEquals(referenceEnd,result.getComparisonEndDate());assertEquals(Long.valueOf(100L),result.getChanges().get("homePv").getChangeAmount());assertEquals(new java.math.BigDecimal("100.00"),result.getChanges().get("homePv").getChangePercent());assertEquals(new java.math.BigDecimal("10.00"),result.getChanges().get("browseOrderConversionPercent").getChangePercentagePoints());assertEquals(Long.valueOf(100L),result.getReference().getHomePv());}
 @Test void summaryRejectsComparisonThatContainsToday(){LocalDate today=LocalDate.now(ZoneId.of("Asia/Shanghai"));DashboardQueryReqVO q=new DashboardQueryReqVO().setScope("SITE").setStartDate(today).setEndDate(today).setCompare(true);assertThrows(IllegalArgumentException.class,()->service(mock(TrafficDailyMapper.class),mock(ProductStatisticsMapper.class)).summary(q,false));}
 @Test void trendReturnsAlignedReferencePointsAndMasksPartialTraffic(){TrafficDailyMapper traffic=mock(TrafficDailyMapper.class);LocalDate start=LocalDate.of(2026,7,1),end=LocalDate.of(2026,7,2),referenceStart=LocalDate.of(2026,6,29),referenceEnd=LocalDate.of(2026,6,30);when(traffic.selectBetween(start,end)).thenReturn(Arrays.asList(new TrafficDailyDO().setDay(start).setHomePv(20L).setProductDetailPv(30L).setPaidRevenue(1000L).setRefundAmount(100L).setTrafficDataStatus(1),new TrafficDailyDO().setDay(end).setHomePv(9L).setProductDetailPv(8L).setPaidRevenue(500L).setRefundAmount(0L).setTrafficDataStatus(2)));when(traffic.selectBetween(referenceStart,referenceEnd)).thenReturn(Arrays.asList(new TrafficDailyDO().setDay(referenceStart).setHomePv(10L).setProductDetailPv(15L).setPaidRevenue(800L).setRefundAmount(0L).setTrafficDataStatus(1),new TrafficDailyDO().setDay(referenceEnd).setHomePv(12L).setProductDetailPv(18L).setPaidRevenue(700L).setRefundAmount(0L).setTrafficDataStatus(1)));List<DashboardTrendItemRespVO> result=service(traffic,mock(ProductStatisticsMapper.class)).trend(new DashboardQueryReqVO().setScope("SITE").setStartDate(start).setEndDate(end).setCompare(true),false);assertEquals(2,result.size());assertEquals(referenceStart,result.get(0).getReferenceDay());assertEquals(Long.valueOf(10L),result.get(0).getReference().getHomePv());assertEquals("PARTIAL",result.get(1).getTrafficDataStatus());assertNull(result.get(1).getHomePv());assertNull(result.get(1).getProductDetailPv());assertEquals(Long.valueOf(500L),result.get(1).getNetRevenue());}
 @Test void profitPermission_exposesProfitWithoutClampingConversion(){TrafficDailyMapper traffic=mock(TrafficDailyMapper.class);when(traffic.selectBetween(any(),any())).thenReturn(Collections.singletonList(new TrafficDailyDO().setProductDetailPv(2L).setPaidOrderCount(3L).setPaidRevenue(1000L).setRefundAmount(0L).setKnownCostAmount(400L).setMissingCostItemCount(0L).setTrafficDataStatus(1).setTrafficWatermark(LocalDateTime.now())));DashboardSummaryRespVO result=service(traffic,mock(ProductStatisticsMapper.class)).summary(new DashboardQueryReqVO(),true);assertEquals(new java.math.BigDecimal("150.00"),result.getBrowseOrderConversionPercent());assertEquals(Long.valueOf(600),result.getGrossProfit());}
 @Test void siteScope_rejectsProductFilter(){DashboardQueryReqVO q=new DashboardQueryReqVO().setScope("SITE").setSpuId(1L);assertThrows(IllegalArgumentException.class,()->service(mock(TrafficDailyMapper.class),mock(ProductStatisticsMapper.class)).summary(q,false));}
 @Test void productPage_usesDatabasePaginationEnrichesAndReturnsTotal(){ProductStatisticsMapper mapper=mock(ProductStatisticsMapper.class);when(mapper.countDashboardProducts(eq(121L),any(),any(),isNull(),isNull(),isNull(),eq(false))).thenReturn(2L);when(mapper.selectDashboardProductPage(eq(121L),any(),any(),isNull(),isNull(),isNull(),eq(false),eq("browseCount"),eq("desc"),eq(0L),eq(1))).thenReturn(Collections.singletonList(row(1L,110)));ProductSpuApi api=mock(ProductSpuApi.class);when(api.getSpuList(anyCollection())).thenReturn(success(Collections.singletonList(spu(1L,8L,"Oak chair"))));DashboardQueryReqVO q=new DashboardQueryReqVO().setScope("PRODUCT").setSortField("browseCount").setSortOrder("desc").setPageNo(1).setPageSize(1);PageResult<DashboardProductRespVO> page=service(mock(TrafficDailyMapper.class),mapper,api).productPage(q,false);assertEquals(Long.valueOf(2),page.getTotal());assertEquals(1,page.getList().size());assertEquals("Oak chair",page.getList().get(0).getProductName());assertEquals(Long.valueOf(110),page.getList().get(0).getBrowseCount());verify(mapper,never()).selectBetween(any(),any());}
 @Test void productPage_rejectsSpuOutsideSelectedCategory(){ProductStatisticsMapper mapper=mock(ProductStatisticsMapper.class);ProductSpuApi api=mock(ProductSpuApi.class);when(api.getSpuList(anyCollection())).thenReturn(success(Collections.singletonList(spu(1L,8L,"Oak chair"))));DashboardQueryReqVO q=new DashboardQueryReqVO().setScope("PRODUCT").setCategoryId(9L).setSpuId(1L);assertThrows(IllegalArgumentException.class,()->service(mock(TrafficDailyMapper.class),mapper,api).productPage(q,false));verifyNoInteractions(mapper);}
 @Test void productCategoryFilterAppliesToSummaryAsWellAsTheTable(){ProductStatisticsMapper mapper=mock(ProductStatisticsMapper.class);when(mapper.selectDashboardSummary(eq(121L),any(),any(),eq(8L),isNull())).thenReturn(row(1L,40));DashboardSummaryRespVO summary=service(mock(TrafficDailyMapper.class),mapper,mock(ProductSpuApi.class)).summary(new DashboardQueryReqVO().setScope("PRODUCT").setCategoryId(8L),false);assertEquals(Long.valueOf(40L),summary.getProductDetailPv());}
 @Test void productPageAppliesTheSelectedOperationalRiskViewInSql(){ProductStatisticsMapper mapper=mock(ProductStatisticsMapper.class);when(mapper.countDashboardProducts(eq(121L),any(),any(),isNull(),isNull(),eq("HIGH_TRAFFIC_LOW_CONVERSION"),eq(false))).thenReturn(1L);when(mapper.selectDashboardProductPage(eq(121L),any(),any(),isNull(),isNull(),eq("HIGH_TRAFFIC_LOW_CONVERSION"),eq(false),eq("paidRevenue"),eq("desc"),eq(0L),eq(100))).thenReturn(Collections.singletonList(row(1L,120)));ProductSpuApi api=mock(ProductSpuApi.class);when(api.getSpuList(anyCollection())).thenReturn(success(Collections.singletonList(spu(1L,8L,"Oak chair"))));PageResult<DashboardProductRespVO> page=service(mock(TrafficDailyMapper.class),mapper,api).productPage(new DashboardQueryReqVO().setScope("PRODUCT").setRiskType("HIGH_TRAFFIC_LOW_CONVERSION"),false);assertEquals(Long.valueOf(1),page.getTotal());assertEquals(Long.valueOf(1),page.getList().get(0).getSpuId());}
 @Test void exportProductsIgnorePaginationAndKeepMetadata(){ProductStatisticsMapper mapper=mock(ProductStatisticsMapper.class);when(mapper.selectDashboardProducts(eq(121L),any(),any(),isNull(),isNull(),isNull(),eq(false),eq("browseCount"),eq("desc"))).thenReturn(Arrays.asList(row(2L,90),row(1L,40)));ProductSpuApi api=mock(ProductSpuApi.class);when(api.getSpuList(anyCollection())).thenReturn(success(Arrays.asList(spu(1L,8L,"Oak chair"),spu(2L,9L,"Linen sofa"))));DashboardQueryReqVO q=new DashboardQueryReqVO().setScope("PRODUCT").setSortField("browseCount").setSortOrder("desc").setPageNo(2).setPageSize(1);List<DashboardProductRespVO> rows=service(mock(TrafficDailyMapper.class),mapper,api).products(q,false);assertEquals(2,rows.size());assertEquals("Linen sofa",rows.get(0).getProductName());assertEquals("Oak chair",rows.get(1).getProductName());}
 @Test void databaseProductAggregationSupportsBigintCountersAndAmounts(){ProductStatisticsMapper mapper=mock(ProductStatisticsMapper.class);ProductStatisticsDO aggregate=new ProductStatisticsDO().setSpuId(1L).setBrowseCount(5_000_000_000L).setOrderCount(3_000_000_000L).setOrderPayPrice(7_000_000_000L).setAfterSaleRefundPrice(300_000_000L).setTrafficDataStatus(1).setProfitDataQuality(1);when(mapper.selectDashboardProducts(eq(121L),any(),any(),isNull(),isNull(),isNull(),eq(false),eq("paidRevenue"),eq("desc"))).thenReturn(Collections.singletonList(aggregate));ProductSpuApi api=mock(ProductSpuApi.class);when(api.getSpuList(anyCollection())).thenReturn(success(Collections.singletonList(spu(1L,8L,"Oak chair"))));DashboardProductRespVO row=service(mock(TrafficDailyMapper.class),mapper,api).products(new DashboardQueryReqVO().setScope("PRODUCT"),false).get(0);assertEquals(Long.valueOf(5_000_000_000L),row.getBrowseCount());assertEquals(Long.valueOf(7_000_000_000L),row.getOrderPayPrice());assertEquals(Long.valueOf(300_000_000L),row.getAfterSaleRefundPrice());}
 @Test void productPageMasksIncompleteTrafficAndCalculatesNetRevenue(){ProductStatisticsMapper mapper=mock(ProductStatisticsMapper.class);ProductStatisticsDO source=new ProductStatisticsDO().setSpuId(1L).setBrowseCount(120L).setBrowseUserCount(80L).setCartCount(5L).setOrderCount(4L).setOrderPayCount(6L).setOrderPayPrice(2000L).setAfterSaleCount(1L).setAfterSaleRefundPrice(300L).setTrafficDataStatus(2).setProfitDataQuality(1);when(mapper.selectDashboardProducts(eq(121L),any(),any(),isNull(),isNull(),isNull(),eq(false),eq("paidRevenue"),eq("desc"))).thenReturn(Collections.singletonList(source));ProductSpuApi api=mock(ProductSpuApi.class);when(api.getSpuList(anyCollection())).thenReturn(success(Collections.singletonList(spu(1L,8L,"Oak chair"))));DashboardProductRespVO row=service(mock(TrafficDailyMapper.class),mapper,api).products(new DashboardQueryReqVO().setScope("PRODUCT"),false).get(0);assertEquals("PARTIAL",row.getTrafficDataStatus());assertNull(row.getBrowseCount());assertNull(row.getBrowseUserCount());assertNull(row.getBrowseConvertPercent());assertEquals(Long.valueOf(5L),row.getCartCount());assertEquals(Long.valueOf(4L),row.getOrderCount());assertEquals(Long.valueOf(1700L),row.getNetRevenue());}
 @Test void productPage_rejectsUnknownSortField(){DashboardQueryReqVO q=new DashboardQueryReqVO().setScope("PRODUCT").setSortField("deleted desc");assertThrows(IllegalArgumentException.class,()->service(mock(TrafficDailyMapper.class),mock(ProductStatisticsMapper.class)).products(q,false));}
 private ProductStatisticsDO row(Long spu,int views){return new ProductStatisticsDO().setSpuId(spu).setBrowseCount((long) views).setTrafficDataStatus(1).setProfitDataQuality(1);}
 private ProductSpuRespDTO spu(Long id,Long category,String name){return new ProductSpuRespDTO().setId(id).setCategoryId(category).setName(name).setPicUrl("https://example.test/"+id+".jpg");}
 private DashboardQueryServiceImpl service(TrafficDailyMapper t,ProductStatisticsMapper p){DashboardQueryServiceImpl s=new DashboardQueryServiceImpl();ReflectionTestUtils.setField(s,"trafficMapper",t);ReflectionTestUtils.setField(s,"productMapper",p);return s;}
 private DashboardQueryServiceImpl service(TrafficDailyMapper t,ProductStatisticsMapper p,ProductSpuApi api){DashboardQueryServiceImpl s=service(t,p);ReflectionTestUtils.setField(s,"productSpuApi",api);return s;}
}
